query CartValidationsGenerateRunInput {
  buyerJourney {
    step
  }
  cart {
    cost {
      subtotalAmount {
        amount
      }
    }
    buyerIdentity {
      purchasingCompany {
        company {
          id
        }
      }
    }
    lines {
      quantity
      merchandise {
        __typename
        ... on ProductVariant {
          sku
          product {
            title
          }
        }
      }
    }
  }
  validation {
    metafield(namespace: "$app:config", key: "min_order") {
      value
    }
  }
}

// src/cart_validations_generate_run.js
export function cartValidationsGenerateRun(input) {
  const errors = [];

  // No carrinho (CART_INTERACTION) só avisamos no checkout, pra não travar a navegação.
  if (input.buyerJourney.step === "CART_INTERACTION") {
    return { operations: [{ validationAdd: { errors } }] };
  }

  const isB2B = Boolean(input.cart.buyerIdentity?.purchasingCompany);
  const min = Number(input.validation?.metafield?.value ?? 0);
  const subtotal = Number(input.cart.cost.subtotalAmount.amount);

  if (isB2B && min > 0 && subtotal < min) {
    const falta = (min - subtotal).toFixed(2);
    errors.push({
      message: `Pedido mínimo de R$ ${min.toFixed(2)}. Faltam R$ ${falta}.`,
      target: "$.cart",
    });
  }

  return { operations: [{ validationAdd: { errors } }] };
}

// erro preso a um campo específico do checkout (ex.: CEP, telefone)
errors.push({
  message: "Não entregamos nesse CEP.",
  target: "$.cart.deliveryGroups[0].deliveryAddress.zip",
});

# grava a configuração da Function (Admin API)
mutation SetConfig($id: ID!, $value: String!) {
  metafieldsSet(metafields: [{
    ownerId: $id,
    namespace: "$app:config",
    key: "min_order",
    type: "number_decimal",
    value: $value
  }]) {
    metafields { id }
    userErrors { field message }
  }
}
